// encode: captured clip frames -> MP4 (H.264/AAC) + poster + silent animated WebP + WebVTT.
// Captions and title cards (poster, intro, outro: src/media/card.ts) are drawn by Chromium (correct Thai shaping with
// the bundled Sarabun); the music bed is generated by code (src/media/music.ts) and loudness-normalised by ffmpeg. It
// plays under every clip, also a ready-made video without sound. No voice, no samples.
import { execFileSync, spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { copyFileSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { extname, join } from 'node:path'
import type { Page } from 'playwright'
import { lazyDep } from './deps.ts'
import { ASSETS } from './paths.ts'
import type { Box, Timeline } from './capture.ts'
import { localize } from './config.ts'
import { type Card, cardBrand, cardHtml } from './media/card.ts'
import { musicWav, seedOf } from './media/music.ts'
import { hasAudio } from './media/probe.ts'
import { animatedWebp } from './media/webp.ts'
import type { Project } from './project.ts'
import { labelsFor, plainText } from './render.ts'
import { type ClipSpec, MANIFEST_FILE, clipDir, clipFiles, clipTimeline, hasClips, loadShots, manifestKey, readManifest } from './shots.ts'
import { UsageError } from './sign.ts'

const playwright = lazyDep<typeof import('playwright')>('playwright')

const FFMPEG = process.env.FFMPEG ?? 'ffmpeg'
/** Bump when the encoded output changes for the same input, so `check` asks for a new encode. */
const ENCODER_VERSION = '4'
/** Target loudness of the music bed (EBU R128 integrated, LUFS). Quiet: it sits under the reading. */
export const MUSIC_LUFS = -20
const FPS = 30
const LOOP_WIDTH = 640
/** Intro and outro title cards of a captured clip (ms). */
export const CARD_MS = 2500
const IMAGE_TYPES: Record<string, string> = { '.png': 'image/png', '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.webp': 'image/webp', '.svg': 'image/svg+xml' }

const imageUrl = (file: string) =>
  existsSync(file) ? `data:${IMAGE_TYPES[extname(file).toLowerCase()] ?? 'image/png'};base64,${readFileSync(file).toString('base64')}` : undefined

/** How a clip is dressed: the poster, and (captured clips) an intro and an outro card around the frames. */
export interface ClipLook {
  poster: 'card' | 'frame'
  cards: boolean
  intro: Card
  outro: Card
}

/**
 * Title cards of a clip: its caption over the title of the book whose page shows it, the brand colour, the book's
 * icon and the logos (document.logos, else the site logo).
 */
export function clipLook(project: Project, spec: ClipSpec, lang: string, id: string): ClipLook {
  const { config, manualDir, primary } = project
  const page = project.pages.find((p) => p.lang === lang && p.tokens.some((t) => t.kind === 'clip' && t.arg === id))
  const book = page ? config.books[page.book] : undefined
  const docTitle = localize(config.document.title, lang, primary)
  const bookTitle = book ? localize(book.title, lang, primary) : docTitle
  const { color, accent, logoFiles, developer } = cardBrand(project, lang)
  const urls = logoFiles.flatMap((f) => imageUrl(f) ?? [])
  const title = plainText(project, lang, localize(spec.caption, lang, primary))
  return {
    poster: spec.poster ?? config.capture.clips.poster,
    cards: !spec.video && (spec.cards ?? config.capture.clips.cards),
    intro: { color, accent, logos: urls, title, subtitle: bookTitle, foot: [docTitle, developer], icon: book?.icon ? imageUrl(join(manualDir, book.icon)) : undefined, done: false },
    outro: { color, accent, logos: urls, title: labelsFor(lang).done, subtitle: page ? plainText(project, lang, page.meta.title) : title, foot: [bookTitle, developer], done: true },
  }
}

/** What the encoded files of a clip were made from: its timeline (frames + timing), its look and the encoder version. */
export function encodeHash(project: Project, spec: ClipSpec, lang: string, id: string): string {
  const file = join(project.manualDir, clipTimeline(lang, id))
  if (!existsSync(file)) return ''
  return createHash('sha256').update(ENCODER_VERSION).update(readFileSync(file)).update(JSON.stringify(clipLook(project, spec, lang, id))).digest('hex').slice(0, 16)
}

/** Captions of a captured clip, moved past the intro card, with a cue for each card. */
export function withCards(segments: Segment[], look: ClipLook): Segment[] {
  const end = (segments.at(-1)?.end ?? 0) + CARD_MS
  return [
    { caption: look.intro.title, start: 0, end: CARD_MS },
    ...segments.map((s) => ({ ...s, start: s.start + CARD_MS, end: s.end + CARD_MS })),
    { caption: look.outro.title, start: end, end: end + CARD_MS },
  ]
}

/** Time to read a caption: at least the captured hold, and about 15 characters a second. */
export const readingMs = (caption: string) => 1500 + [...caption].length * 65

export interface Segment {
  caption: string
  start: number
  end: number
}

/** Frame durations after making room to read each caption, and the segment times (ms). */
export function plan(t: Timeline, captions: string[]): { durations: number[]; segments: Segment[] } {
  const durations = t.frames.map((f) => (f.end ? Math.max(f.ms, readingMs(captions[f.segment] ?? '')) : f.ms))
  const segments: Segment[] = []
  let at = 0
  t.frames.forEach((f, i) => {
    const s = (segments[f.segment] ??= { caption: captions[f.segment] ?? '', start: at, end: at })
    s.end = at + durations[i]!
    at += durations[i]!
  })
  return { durations, segments: segments.filter(Boolean) }
}

/** Room kept around a highlight: the red frame is drawn 5px outside the element. */
const HIGHLIGHT_PAD = 8

/**
 * Where a segment's caption band goes: at the bottom, unless it would cover the segment's highlight; then at the top,
 * unless that covers it too; then on the side that covers less of it (bottom on a tie).
 */
export function captionSide(box: Box | undefined, height: number, band: number): 'top' | 'bottom' {
  if (!box) return 'bottom'
  const y0 = box.y - HIGHLIGHT_PAD
  const y1 = box.y + box.height + HIGHLIGHT_PAD
  const bottom = Math.max(0, y1 - Math.max(y0, height - band))
  if (!bottom) return 'bottom'
  const top = Math.max(0, Math.min(y1, band) - y0)
  return top < bottom ? 'top' : 'bottom'
}

const vttTime = (ms: number) => {
  const h = Math.floor(ms / 3_600_000)
  const m = Math.floor((ms % 3_600_000) / 60_000)
  const s = ((ms % 60_000) / 1000).toFixed(3).padStart(6, '0')
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${s}`
}
/** Cue text is markup in WebVTT: & < > are written as entities so the player shows them as written. */
const vttText = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
export const toVtt = (segments: Segment[]) =>
  `WEBVTT\n\n${segments.map((s, i) => `${i + 1}\n${vttTime(s.start)} --> ${vttTime(s.end)}\n${vttText(s.caption)}\n`).join('\n')}`

/** The highlight frame capture draws (3px, #d1242f) found in a frame picture, as the element's box. */
async function findHighlight(page: Page, src: string): Promise<Box | undefined> {
  return page.evaluate(async (src) => {
    const img = new Image()
    img.src = src
    await img.decode()
    const c = document.createElement('canvas')
    c.width = img.naturalWidth
    c.height = img.naturalHeight
    const g = c.getContext('2d', { willReadFrequently: true })!
    g.drawImage(img, 0, 0)
    const d = g.getImageData(0, 0, c.width, c.height).data
    let x0 = Infinity
    let y0 = Infinity
    let x1 = -1
    let y1 = -1
    let count = 0
    for (let y = 0; y < c.height; y++)
      for (let x = 0; x < c.width; x++) {
        const i = (y * c.width + x) * 4
        if (d[i] !== 209 || d[i + 1] !== 36 || d[i + 2] !== 47) continue
        count++
        x0 = Math.min(x0, x)
        y0 = Math.min(y0, y)
        x1 = Math.max(x1, x)
        y1 = Math.max(y1, y)
      }
    // the frame is drawn 5px outside the element
    return count < 20 ? undefined : { x: x0 + 5, y: y0 + 5, width: Math.max(0, x1 - x0 - 9), height: Math.max(0, y1 - y0 - 9) }
  }, src)
}

export function hasFfmpeg(): boolean {
  return spawnSync(FFMPEG, ['-version'], { stdio: 'ignore' }).status === 0
}

export interface EncodeResult {
  encoded: { lang: string; id: string; seconds: number }[]
  skipped: { lang: string; id: string; reason: string }[]
}

const FONT = new URL('fonts/Sarabun-SemiBold.ttf', ASSETS)
const BOLD = new URL('fonts/Sarabun-Bold.ttf', ASSETS)

/** A title card as a PNG of the clip's size. */
async function renderCard(page: Page, card: Card, width: number, height: number, fonts: { semibold: string; bold: string }, out: string): Promise<void> {
  await page.setViewportSize({ width, height })
  await page.setContent(cardHtml(card, width, height, fonts))
  await page.evaluate(() => document.fonts.ready.then(() => undefined))
  await page.screenshot({ path: out })
}

/** A picture scaled to `w` x `h` as a still WebP (Chromium's encoder). */
function toWebp(page: Page, png: Buffer, w: number, h: number): Promise<Buffer> {
  return page
    .evaluate(
      async ({ src, w, h }) => {
        const img = new Image()
        img.src = src
        await img.decode()
        const c = document.createElement('canvas')
        c.width = w
        c.height = h
        const g = c.getContext('2d', { alpha: false })!
        g.imageSmoothingQuality = 'high'
        g.drawImage(img, 0, 0, w, h)
        return c.toDataURL('image/webp', 0.8).split(',')[1]!
      },
      { src: `data:image/png;base64,${png.toString('base64')}`, w, h },
    )
    .then((b64) => Buffer.from(b64, 'base64'))
}

const BITEXACT = ['-map_metadata', '-1', '-fflags', '+bitexact', '-flags:v', '+bitexact', '-flags:a', '+bitexact']

export async function runEncode(project: Project, opts: { lang?: string; changed?: boolean } = {}): Promise<EncodeResult> {
  const { config, manualDir, primary } = project
  if (!hasClips(config.media)) throw new UsageError(`clips need media level "steps+video" (now "${config.media}")`)
  if (!hasFfmpeg()) throw new UsageError('ffmpeg not found (install it, or set FFMPEG=/path/to/ffmpeg)')
  const shots = loadShots(manualDir)
  const manifest = readManifest(manualDir)
  const result: EncodeResult = { encoded: [], skipped: [] }
  const jobs: { lang: string; id: string }[] = []
  for (const lang of config.languages) {
    if (opts.lang && opts.lang !== lang) continue
    for (const id of Object.keys(shots.clips)) {
      if (!existsSync(join(manualDir, clipTimeline(lang, id)))) {
        result.skipped.push({ lang, id, reason: 'not captured (run "manual-kit capture")' })
        continue
      }
      const fresh = manifest[manifestKey(lang, 'encode', id)] === encodeHash(project, shots.clips[id]!, lang, id) && Object.values(clipFiles(lang, id)).every((x) => existsSync(join(manualDir, x)))
      if (opts.changed && fresh) continue
      jobs.push({ lang, id })
    }
  }
  if (!jobs.length) return result

  const font = readFileSync(FONT).toString('base64')
  const fonts = { semibold: font, bold: readFileSync(BOLD).toString('base64') }
  const browser = await playwright.chromium.launch()
  try {
    for (const { lang, id } of jobs) {
      const spec = shots.clips[id]!
      const dir = join(manualDir, clipDir(lang, id))
      const t = JSON.parse(readFileSync(join(manualDir, clipTimeline(lang, id)), 'utf8')) as Timeline
      const look = clipLook(project, spec, lang, id)
      const work = join(manualDir, config.outputs.dir, '.build', 'clips', `${lang}-${id}`)
      rmSync(work, { recursive: true, force: true })
      mkdirSync(work, { recursive: true })
      const f = clipFiles(lang, id)
      const loopH = Math.round((t.height * LOOP_WIDTH) / t.width)
      if (spec.video) {
        // used as it is, with the music bed when it has no sound; a poster (title card or frame), a still WebP of it,
        // and its captions
        const src = join(manualDir, spec.video.file)
        const total = t.frames.reduce((a, x) => a + x.ms, 0)
        const seconds = total / 1000
        if (hasAudio(src)) copyFileSync(src, join(manualDir, f.mp4))
        else {
          writeFileSync(join(work, 'music.wav'), musicWav(seconds, seedOf(id)))
          execFileSync(
            FFMPEG,
            [
              ...['-hide_banner', '-loglevel', 'error', '-y', '-i', src, '-i', join(work, 'music.wav')],
              ...['-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy', '-af', `loudnorm=I=${MUSIC_LUFS}:TP=-2:LRA=7,aresample=48000`],
              ...['-c:a', 'aac', '-b:a', '128k', '-ar', '48000', '-t', seconds.toFixed(3), '-movflags', '+faststart', ...BITEXACT],
              join(manualDir, f.mp4),
            ],
            { stdio: ['ignore', 'ignore', 'pipe'] },
          )
        }
        const page = await browser.newPage({ viewport: { width: t.width, height: t.height }, deviceScaleFactor: 1 })
        if (look.poster === 'card') await renderCard(page, look.intro, t.width, t.height, fonts, join(manualDir, f.poster))
        else {
          const at = Math.min(spec.video.posterAt, Math.max(0, seconds - 0.1))
          execFileSync(FFMPEG, ['-hide_banner', '-loglevel', 'error', '-y', '-ss', at.toFixed(3), '-i', src, '-frames:v', '1', join(manualDir, f.poster)], { stdio: ['ignore', 'ignore', 'pipe'] })
        }
        writeFileSync(join(manualDir, f.webp), await toWebp(page, readFileSync(join(manualDir, f.poster)), LOOP_WIDTH, loopH))
        await page.close()
        if (spec.video.captions) copyFileSync(join(manualDir, spec.video.captions), join(manualDir, f.vtt))
        else writeFileSync(join(manualDir, f.vtt), 'WEBVTT\n')
        manifest[manifestKey(lang, 'encode', id)] = encodeHash(project, spec, lang, id)
        result.encoded.push({ lang, id, seconds })
        continue
      }
      const captions = spec.segments.map((s) => plainText(project, lang, localize(s.caption, lang, primary)))
      const { durations, segments } = plan(t, captions)
      const total = durations.reduce((a, b) => a + b, 0) + (look.cards ? 2 * CARD_MS : 0)

      // 1. captions onto every frame (Chromium), plus a small WebP of each for the silent loop
      const page = await browser.newPage({ viewport: { width: t.width, height: t.height }, deviceScaleFactor: 1 })
      const fontPx = Math.max(18, Math.round(t.width * 0.022))
      await page.setContent(`<!doctype html><html><head><meta charset="utf-8"><style>
@font-face { font-family: 'Sarabun'; src: url(data:font/ttf;base64,${font}) format('truetype'); font-weight: 600; }
html, body { margin: 0; width: ${t.width}px; height: ${t.height}px; overflow: hidden; background: #fff; }
#shot { display: block; width: ${t.width}px; height: ${t.height}px; }
#bar { position: absolute; left: 0; right: 0; bottom: 0; display: flex; align-items: center; gap: ${Math.round(fontPx * 0.7)}px;
  padding: ${Math.round(fontPx * 0.6)}px ${Math.round(fontPx * 1.2)}px; background: rgba(15, 20, 25, 0.86); color: #fff;
  font: 600 ${fontPx}px/1.45 'Sarabun', sans-serif; }
#n { flex: none; min-width: ${Math.round(fontPx * 1.6)}px; height: ${Math.round(fontPx * 1.6)}px; border-radius: 999px; background: #d1242f;
  display: grid; place-items: center; font-size: ${Math.round(fontPx * 0.8)}px; }
#t { flex: 1; }
</style></head><body><img id="shot" alt=""><div id="bar"><span id="n"></span><span id="t"></span></div></body></html>`)
      await page.evaluate(() => document.fonts.ready.then(() => undefined))
      const framePng = (file: string) => `data:image/png;base64,${readFileSync(join(dir, file)).toString('base64')}`
      // each segment's highlight: recorded by capture, or (timelines from before that) the red frame found in the picture
      const boxes: (Box | undefined)[] = []
      for (const f of t.frames) if (f.end) boxes[f.segment] = f.box ?? (await findHighlight(page, framePng(f.file)))
      const loop: { webp: Buffer; ms: number }[] = []
      for (const [i, f] of t.frames.entries()) {
        const band = await page.evaluate(
          async ({ src, n, text }) => {
            const img = document.getElementById('shot') as HTMLImageElement
            img.src = src
            await img.decode()
            document.getElementById('n')!.textContent = n
            document.getElementById('t')!.textContent = text
            return document.getElementById('bar')!.offsetHeight
          },
          { src: framePng(f.file), n: `${f.segment + 1}/${spec.segments.length}`, text: captions[f.segment] ?? '' },
        )
        // one side per segment, so the band does not jump while its caption is on screen
        const top = captionSide(boxes[f.segment], t.height, band) === 'top'
        await page.evaluate((top) => {
          const bar = document.getElementById('bar')!
          bar.style.top = top ? '0' : 'auto'
          bar.style.bottom = top ? 'auto' : '0'
        }, top)
        const out = join(work, `c-${String(i + 1).padStart(3, '0')}.png`)
        const shot = await page.screenshot({ path: out })
        loop.push({ webp: await toWebp(page, shot, LOOP_WIDTH, loopH), ms: durations[i]! })
      }
      // title cards: the intro (also the poster) and the outro
      if (look.cards || look.poster === 'card') await renderCard(page, look.intro, t.width, t.height, fonts, join(work, 'intro.png'))
      if (look.cards) await renderCard(page, look.outro, t.width, t.height, fonts, join(work, 'outro.png'))
      await page.close()

      // 2. video: (intro card) frames with their durations (outro card), a short fade in/out, music bed normalised to MUSIC_LUFS
      const entry = (file: string, ms: number) => `file '${file}'\nduration ${(ms / 1000).toFixed(3)}`
      const list = t.frames.map((_, i) => entry(`c-${String(i + 1).padStart(3, '0')}.png`, durations[i]!))
      if (look.cards) list.unshift(entry('intro.png', CARD_MS))
      if (look.cards) list.push(entry('outro.png', CARD_MS))
      list.push(look.cards ? `file 'outro.png'` : `file 'c-${String(t.frames.length).padStart(3, '0')}.png'`)
      writeFileSync(join(work, 'frames.txt'), `${list.join('\n')}\n`)
      const seconds = total / 1000
      writeFileSync(join(work, 'music.wav'), musicWav(seconds, seedOf(`${id}`)))
      const fadeOut = Math.max(0, seconds - 0.6).toFixed(3)
      execFileSync(
        FFMPEG,
        [
          ...['-hide_banner', '-loglevel', 'error', '-y'],
          ...['-f', 'concat', '-safe', '0', '-i', join(work, 'frames.txt')],
          ...['-i', join(work, 'music.wav')],
          ...['-vf', `fps=${FPS},scale=trunc(iw/2)*2:trunc(ih/2)*2,format=yuv420p,fade=t=in:st=0:d=0.4,fade=t=out:st=${fadeOut}:d=0.6`],
          ...['-af', `loudnorm=I=${MUSIC_LUFS}:TP=-2:LRA=7,aresample=48000`],
          ...['-c:v', 'libx264', '-preset', 'medium', '-crf', '20', '-tune', 'stillimage', '-pix_fmt', 'yuv420p', '-r', String(FPS)],
          ...['-c:a', 'aac', '-b:a', '128k', '-ar', '48000'],
          ...['-t', seconds.toFixed(3), '-movflags', '+faststart', ...BITEXACT],
          join(manualDir, f.mp4),
        ],
        { stdio: ['ignore', 'ignore', 'pipe'] },
      )

      // 3. poster (the title card, or the end of the first segment), silent loop, captions as WebVTT
      const posterFrame = `c-${String(t.frames.findIndex((x) => x.end) + 1).padStart(3, '0')}.png`
      copyFileSync(join(work, look.poster === 'card' ? 'intro.png' : posterFrame), join(manualDir, f.poster))
      writeFileSync(join(manualDir, f.webp), animatedWebp(loop, LOOP_WIDTH, loopH))
      writeFileSync(join(manualDir, f.vtt), toVtt(look.cards ? withCards(segments, look) : segments))
      manifest[manifestKey(lang, 'encode', id)] = encodeHash(project, spec, lang, id)
      result.encoded.push({ lang, id, seconds })
    }
  } finally {
    await browser.close()
    const sorted = Object.fromEntries(Object.entries(manifest).sort(([a], [b]) => (a < b ? -1 : 1)))
    writeFileSync(join(manualDir, MANIFEST_FILE), `${JSON.stringify(sorted, null, 2)}\n`)
  }
  return result
}
